const GlassNotification = ({ name, description, icon, color, time }: NotificationItem) => {
  return (
    <figure
      className={cn(
        "relative mx-auto min-h-fit w-full max-w-[380px] cursor-pointer overflow-hidden rounded-2xl p-4",
        "transition-all duration-200 ease-in-out hover:scale-[102%] hover:border-violet-400/30",
        // dark-purple glassmorphism: translucent violet tint, blurred, soft inner highlight + outer glow
        "border border-violet-300/10 bg-gradient-to-br from-violet-950/60 via-indigo-950/50 to-fuchsia-950/40 backdrop-blur-2xl",
        "shadow-[0_8px_32px_rgba(76,29,149,0.35),0_0_0_1px_rgba(139,92,246,0.05)_inset]",
        "before:pointer-events-none before:absolute before:inset-0 before:rounded-2xl before:bg-gradient-to-br before:from-white/10 before:via-violet-400/5 before:to-transparent",
        "after:pointer-events-none after:absolute after:-inset-px after:rounded-2xl after:bg-gradient-to-b after:from-violet-300/10 after:to-transparent after:opacity-60"
      )}
    >
      <div className="relative flex flex-row items-center gap-3">
        <div
          className="flex size-9 shrink-0 items-center justify-center rounded-full shadow-[0_2px_10px_rgba(0,0,0,0.35)] ring-1 ring-white/10"
          style={{ backgroundColor: color }}
        >
          <span className="text-base leading-none">{icon}</span>
        </div>
        <div className="flex min-w-0 flex-col">
          <figcaption className="flex flex-row items-center gap-1 whitespace-pre text-sm font-medium text-white/90">
            <span className="truncate">{name}</span>
            <span className="text-violet-300/40">·</span>
            <span className="text-xs font-normal text-violet-200/40">{time}</span>
          </figcaption>
          <p className="truncate text-xs font-normal text-violet-100/50">
            {description}
          </p>
        </div>
      </div>
    </figure>
  );
};

